65		const receiptService = new ReceiptService(supabase);
66	
67		let session: Session | null = $state(null);
68		let familyId: string | null = $state(null);
69		let expenses: Expense[] = $state([]);
70		let categories: Category[] = $state([]);
71		// Spending-hierarchy Groupings, offered when creating a new category inline so
72		// it can be filed straight away rather than landing in Uncategorized.
73		let groups: CategoryGroup[] = $state([]);
74		// #{#rf09} Resolve each row's Category once per (expenses, categories) change
75		// instead of an O(rows × categories) find() per table render.
76		let categoryByReceipt = $derived(buildCategoryMap(expenses, categories));
77		let loading = $state(true);
78		let error: string | null = $state(null);
79		let expenseSelection = $state(emptySelection());
80		let isDeleting = $state(false);
81	
82		// #{#exp6a} - Uncategorized filter state
83		let showUncategorizedOnly = $state(false);
84	
85		// #{#exp7a} - Category filter state
86		let selectedCategoryIds: string[] = $state([]);
87	
88		// #{#edf1a} - URL-based date filter state (read from query parameters)
89		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
90		let urlDateFrom = $derived(urlDateFilter.dateFrom);
91		let urlDateTo = $derived(urlDateFilter.dateTo);
92	
93		// #{#edf1a} - Temporary date filter inputs (before "Apply" is clicked)
94		let tempFilterDateFrom = $state('');
95		let tempFilterDateTo = $state('');
96	
97		// #{#edf1a} - Sync temp values when URL changes
98		$effect(() => {
99			tempFilterDateFrom = urlDateFrom;
100			tempFilterDateTo = urlDateTo;
101		});
102	
103		// #{#exr1b} - Receipt edit modal state
104		let editingReceipt: ReceiptRow | null = $state(null);
105		let editingExpense: Expense | null = $state(null);
106		let showEditModal = $state(false);
107		let isSaving = $state(false);
108		let successMessage: string | null = $state(null);
109	
110		// #{#exp1a} #{#exp3b} - CSV Export state
111		let isExporting = $state(false);
112		const csvService = new CSVExportService();
113	
114		// #{#cre1a} #{#cre4a} - PDF Export state
115		let isExportingPDF = $state(false);
116		let pdfExportProgress = $state('');
117		let pdfAbortController: AbortController | null = $state(null);
118		const pdfService = new PDFExportService();
119	
120		onMount(async () => {
121			// #{#exp1a} Criterion 7: Verify authentication
122			const { data } = await supabase.auth.getSession();
123			session = data.session;
124	
125			if (!session) {
126				return;
127			}
128	
129			// Get user's default family
130			familyId = await getDefaultFamilyId();
131	
132			if (!familyId) {
133				error = 'No family found. Please contact support.';
134				return;
135			}
136	
137			// #{#exp1b} Load expenses derived from receipts
138			await loadExpenses();
139	
140			// Load family categories for dropdown
141			await loadCategories();
142	
143			// #{#vca5a} Check for auto-categorization matches on page load
144			await checkForAutoCategorizationMatches();
145		});
146	
147		/**
148		 * Load expenses from receipts using ExpenseService
149		 * #{#exp1b} - Expenses derived from receipts
150		 */
151		async function loadExpenses() {
152			if (!session?.user) return;
153	
154			try {
155				loading = true;
156				error = null;
157	
158				const expenseService = new ExpenseService(supabase);
159				expenses = await expenseService.getExpenses(session.user.id);
160			} catch (err) {
161				console.error('Error loading expenses:', err);
162				error = err instanceof Error ? err.message : 'Failed to load expenses';
163			} finally {
164				loading = false;
165			}
166		}
167	
168		// #{#exp6b} Selection-based bulk delete. An expense IS a receipt (1:1, computed),
169		// so this deletes the underlying receipts (record + stored file).
170		async function deleteSelected(): Promise<void> {
171			const receiptIds = Array.from(expenseSelection.selected);
172			if (receiptIds.length === 0) return;
173			if (
174				!confirm(
175					`Delete ${receiptIds.length} selected expense${receiptIds.length === 1 ? '' : 's'}? This removes the underlying receipt and its stored file.`
176				)
177			) {
178				return;
179			}
180	
181			isDeleting = true;
182			error = null;
183			const originalExpenses = expenses;
184			// Optimistic update — remove from UI immediately
185			expenses = expenses.filter((e) => !expenseSelection.selected.has(e.receipt_id));
186	
187			try {
188				await receiptService.bulkDeleteReceipts(receiptIds);
189				expenseSelection = emptySelection();
190				showToast(
191					`Deleted ${receiptIds.length} expense${receiptIds.length === 1 ? '' : 's'}`,
192					'success'
193				);
194			} catch (err) {
195				// Rollback on failure
196				expenses = originalExpenses;
197				error = err instanceof Error ? err.message : 'Failed to delete expenses';
198			} finally {
199				isDeleting = false;
200			}
201		}
202	
203		// Apply one category to many expenses in a single batched upsert. Used when the
204		// user picks a category on a row that is part of a multi-row selection — the
205		// change fans out to the whole selection. Unlike the single-row flow it does
206		// NOT auto-create a vendor rule: the selection spans many merchants, so there
207		// is no one merchant to attach a rule to.
208		async function applyCategoryToSelection(receiptIds: string[], category: Category): Promise<void> {
209			error = null;
210			try {
211				const expenseService = new ExpenseService(supabase);
212				await expenseService.bulkAssignCategory(receiptIds, category.id, 'manual');
213				expenseSelection = emptySelection();
214				await loadExpenses();
215				showToast(`Set ${receiptIds.length} expenses to ${category.name}`, 'success');
216			} catch (err) {
217				error = err instanceof Error ? err.message : 'Failed to recategorize expenses';
218			}
219		}
220	
221		/**
222		 * Check for and apply vendor rule matches to uncategorized expenses
223		 * #{#vca5a} - Batch Auto-Categorization on Page Load
224		 */
225		async function checkForAutoCategorizationMatches() {
226			if (!familyId) return;
227	
228			try {
229				const expenseService = new ExpenseService(supabase);
230	
231				// Apply all family vendor rules to current expenses
232				const totalAssigned = await expenseService.applyAllVendorRules(familyId, expenses);
233	
234				// If any expenses were auto-assigned, reload and notify user
235				if (totalAssigned > 0) {
236					await loadExpenses();
237					showToast(
238						`Auto-categorized ${totalAssigned} expense${totalAssigned === 1 ? '' : 's'} based on vendor rules`,
239						'success'
240					);
241				}
242			} catch (err) {
243				console.error('Error checking auto-categorization:', err);
244				// Don't show error to user - this is a background operation
245			}
246		}
247	
248		/**
249		 * Load family categories for dropdown
250		 * #{#exp2a} - Category Assignment UI
251		 * #{#exp3a} - Auto-initialize default categories for new families
252		 */
253		async function loadCategories() {
254			if (!familyId) return;
255	
256			try {
257				const categoryService = new CategoryService(supabase);
258				categories = await categoryService.getFamilyCategories(familyId);
259	
260				// Auto-initialize default categories for families with no categories
261				// #{#exp3a} Requirement 2 & 3
262				if (categories.length === 0) {
263					await categoryService.createDefaultCategories(familyId);
264					categories = await categoryService.getFamilyCategories(familyId);
265				}
266	
267				// Groupings power the "Group" selector in inline category creation.
268				// Best-effort: a family without a seeded hierarchy simply gets no
269				// selector (the feature degrades to the previous behaviour).
270				groups = await categoryService.getFamilyGroups(familyId);
271			} catch (err) {
272				console.error('Error loading categories:', err);
273			}
274		}
275	
276		/**
277		 * Handle category assignment
278		 * #{#exp2a} - Category Assignment UI
279		 * #{#exp5b} - Manual Override Precedence
280		 * #{#exp5a} - Auto-create vendor rules on first categorization
281		 */
282		async function handleCategorySelect(receiptId: string, category: Category) {
283			// If this row is part of a multi-row selection, the pick fans out to every
284			// selected expense (no separate bulk control needed). A single checked row
285			// falls through to the normal single-row path so its vendor rule is still
286			// auto-created.
287			const selected = expenseSelection.selected;
288			if (selected.has(receiptId) && selected.size > 1) {
289				await applyCategoryToSelection(Array.from(selected), category);
290				return;
291			}
292	
293			try {
294				const expenseService = new ExpenseService(supabase);
295	
296				// 1. Assign category to this expense
297				await expenseService.assignCategory(receiptId, category.id, 'manual');
298	
299				// 2. Auto-create vendor rule if none exists
300				// Find the expense to get merchant_name
301				const expense = expenses.find((e) => e.receipt_id === receiptId);
302				if (expense && familyId) {
303					// Check if rule already exists
304					const existingRule = await expenseService.getVendorRule(familyId, expense.merchant_name);
305	
306					// Only create rule if none exists (silent auto-creation)
307					if (!existingRule) {
308						await expenseService.createVendorRule(familyId, expense.merchant_name, category.id);
309	
310						// #{#vca1a} Apply rule to visible expenses after creating it
311						const vendorPattern = expenseService.normalizeVendor(expense.merchant_name);
312						const appliedCount = await expenseService.applyRuleToVisibleExpenses(
313							filteredExpenses,
314							vendorPattern,
315							category.id
316						);
317	
318						// #{#vca3a} Show user feedback if expenses were auto-assigned
319						if (appliedCount > 0) {
320							showToast(
321								`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
322								'success'
323							);
324						}
325					}
326					// If rule exists, user must click "change default" in dropdown to update it
327				}
328	
329				// 3. Reload expenses to reflect the change
330				await loadExpenses();
331			} catch (err) {
332				console.error('Error assigning category:', err);
333				error = err instanceof Error ? err.message : 'Failed to assign category';
334			}
335		}
336	
337		/**
338		 * Handle inline category creation from CategoryDropdown
339		 * #{#exp3b} - Create New Category Inline
340		 */
341		async function handleCreateNewCategory(data: {
342			name: string;
343			color: string | null;
344			groupId: string | null;
345		}) {
346			try {
347				const categoryService = new CategoryService(supabase);
348				await categoryService.createCategory(
349					familyId || '',
350					data.name,
351					data.color || undefined,
352					data.groupId
353				);
354				await loadCategories();
355				showToast(`Created category: ${data.name}`, 'success');
356			} catch (err) {
357				console.error('Error creating category:', err);
358				showToast(err instanceof Error ? err.message : 'Failed to create category', 'error');
359			}
360		}
