362		/**
363		 * Handle vendor rule creation from CategoryDropdown
364		 * #{#vca1a} - Apply rules to visible expenses when rule is created/updated
365		 * #{#vca3a} - Show user feedback for auto-assignment
366		 */
367		async function handleVendorRuleCreated(data: { merchantName: string; categoryId: string }) {
368			try {
369				const { merchantName, categoryId } = data;
370				const expenseService = new ExpenseService(supabase);
371	
372				// Get category name for feedback
373				const category = findCategoryById(categories, categoryId);
374				if (!category) return;
375	
376				// Apply rule to visible expenses
377				const vendorPattern = expenseService.normalizeVendor(merchantName);
378				const appliedCount = await expenseService.applyRuleToVisibleExpenses(
379					filteredExpenses,
380					vendorPattern,
381					categoryId
382				);
383	
384				// Show user feedback
385				if (appliedCount > 0) {
386					showToast(
387						`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
388						'success'
389					);
390				}
391	
392				// Reload expenses to reflect the changes
393				await loadExpenses();
394			} catch (err) {
395				console.error('Error applying vendor rule:', err);
396				error = err instanceof Error ? err.message : 'Failed to apply vendor rule';
397			}
398		}
