400		// formatCurrency imported from $lib/utils/formatCurrency
401	
402		// formatDate imported from $lib/utils/dateConversion
403	
404		/**
405		 * #{#exp6a} Criterion 2: Filter uncategorized expenses
406		 * #{#exp7a} Criterion 2 & 4: Filter by category (OR logic for multiple)
407		 * #{#edf1a} Criterion 6 & 8: Filter by date range from URL (works with category filters)
408		 */
409		let filteredExpenses = $derived(
410			expenses.filter((expense) => {
411				// #{#edf1a} Date range filter (from URL parameters)
412				if (!matchesDateRange(expense.transaction_date, urlDateFrom, urlDateTo)) {
413					return false;
414				}
415	
416				// #{#exp6a} Uncategorized filter takes precedence
417				if (showUncategorizedOnly) {
418					return expense.category_id === null;
419				}
420	
421				// #{#exp7a} Category filter (OR logic)
422				if (selectedCategoryIds.length > 0) {
423					return expense.category_id && selectedCategoryIds.includes(expense.category_id);
424				}
425	
426				// No filters active, show all
427				return true;
428			})
429		);
430	
431		/**
432		 * #{#exp6a} Criterion 3: Count uncategorized expenses
433		 * #{#flt1a} Use filteredExpenses to reflect current filter state
434		 */
435		let uncategorizedCount = $derived(filteredExpenses.filter((e) => e.category_id === null).length);
436	
437		/**
438		 * #{#exp7a} Criterion 3: Count expenses per category
