654				// #{#exp4b} Criterion 2: Export filtered expenses
655				const csvContent = csvService.exportExpensesToCSV(filteredExpenses);
656	
657				// #{#edf2a} Criterion 2: Generate filename based on current filters
658				// (date range wins over category filters — logic in CSVExportService).
659				const filename = csvService.expenseExportFilename({
660					dateFrom: urlDateFrom,
661					dateTo: urlDateTo,
662					uncategorizedOnly: showUncategorizedOnly,
663					selectedCategoryNames: selectedCategoryIds.map(
664						(id) => findCategoryById(categories, id)?.name ?? ''
665					)
666				});
