688		/**
689		 * #{#cre1a} #{#cre4b} Handle PDF receipt export
690		 * #{#cre1b} Respects current filters (exports filteredExpenses)
691		 * #{#cre4a} Shows progress and supports cancellation
692		 */
693		async function handleExportPDF() {
694			if (!pdfExportEnabled) return;
695	
696			isExportingPDF = true;
697			pdfExportProgress = 'Preparing receipt data...';
698			pdfAbortController = new AbortController();
699	
700			try {
701				// #{#cre1b} Build category names for the selected filters
702				const selectedCategories = categories.filter((c) => selectedCategoryIds.includes(c.id));
703				const categoryNames = selectedCategories.map((c) => c.name);
704	
705				// #{#cre3a} Fetch receipt images via signed URLs
706				const fetchImageFn = async (path: string): Promise<Uint8Array | null> => {
707					const signedUrl = await getSignedReceiptUrl(path, 300); // 5 min expiry
708					if (!signedUrl) return null;
709					const response = await fetch(signedUrl);
710					if (!response.ok) return null;
711					const buffer = await response.arrayBuffer();
712					return new Uint8Array(buffer);
713				};
714	
715				// #{#cre1b} Build date range from URL filters
716				const dateRange =
717					urlDateFrom && urlDateTo
718						? { start: urlDateFrom, end: urlDateTo }
719						: urlDateFrom
720							? { start: urlDateFrom, end: urlDateFrom }
721							: null;
722	
723				const pdfBytes = await pdfService.generateReceiptPDF(filteredExpenses, {
724					categories: selectedCategories,
725					dateRange,
726					fetchImageFn,
727					abortSignal: pdfAbortController.signal,
728					onProgress: (step: string) => {
729						pdfExportProgress = step;
730					}
731				});
732	
733				// #{#cre3b} Generate filename and download
734				const filename = pdfService.generateFilename(categoryNames, dateRange);
735				pdfService.downloadPDF(pdfBytes, filename);
736	
737				// #{#cre4a} Success feedback
738				const totalAmount = pdfService.calculateSubtotal(filteredExpenses);
739				showToast(
740					`PDF exported: ${filteredExpenses.length} receipt${filteredExpenses.length !== 1 ? 's' : ''} across ${categoryNames.length} categor${categoryNames.length !== 1 ? 'ies' : 'y'}, ${pdfService.formatAmount(totalAmount)} total`,
741					'success'
742				);
743			} catch (err) {
744				if (err instanceof Error && /abort|cancel/i.test(err.message)) {
745					showToast('PDF export cancelled', 'success');
746				} else {
747					console.error('Error exporting PDF:', err);
748					showToast(
749						`Failed to generate PDF: ${err instanceof Error ? err.message : 'Unknown error'}`,
750						'error'
751					);
752				}
753			} finally {
754				isExportingPDF = false;
755				pdfExportProgress = '';
756				pdfAbortController = null;
757			}
758		}
