783	
784		async function loadSignedUrls(paths: string[]) {
785			const cached = signedUrls;
786			const newUrls: Record<string, string> = {};
787			const missing: string[] = [];
788			for (const path of paths) {
789				if (cached[path]) newUrls[path] = cached[path];
790				else missing.push(path);
791			}
792			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
793			if (missing.length > 0) {
794				Object.assign(newUrls, await getSignedReceiptUrls(missing));
795			}
796			signedUrls = newUrls;
797		}
798	
799		function getImageUrl(path: string | null): string | null {
800			if (!path) return null;
801			return signedUrls[path] ?? null;
802		}
