1	<script lang="ts">
2		/**
3		 * Receipt Image Viewer Component
4		 *
5		 * Provides zoom and pan capabilities for receipt images in a floating modal.
6		 * Implements specifications #{#zom1a} through #{#zom5b} from
7		 * specs/specifications/receipt-image-zoom-pan.md
8		 *
9		 * Zoom anchors to cursor position (mouse wheel, pinch midpoint, double-tap).
10		 * Scrollable container replaces manual pan — native scrollbars + drag-to-scroll.
11		 *
12		 * @component
13		 */
14	
15		// Props — #{#pdf1a} added isPdf for PDF detection
16		interface Props {
17			imageUrl: string;
18			altText?: string;
19			show?: boolean;
20			isPdf?: boolean;
21			onclose?: () => void;
22		}
23	
24		let {
25			imageUrl,
26			altText = 'Receipt image',
27			show = false,
28			isPdf = false,
29			onclose
30		}: Props = $props();
31	
32		// Zoom state - #{#zom1a}
33		let zoom = $state(100);
34	
35		// Drag-to-scroll state - #{#zom2a}
36		let isDragging = $state(false);
37		let dragStartX = $state(0);
38		let dragStartY = $state(0);
39		let scrollStartX = $state(0);
40		let scrollStartY = $state(0);
41	
42		// Touch gesture state - #{#zom3a}
43		let touchStartDistance = $state(0);
44		let touchStartZoom = $state(100);
45		let lastTapTime = $state(0);
46	
47		// Image base dimensions (fit-to-viewport at 100%)
48		let baseWidth = $state(0);
49		let baseHeight = $state(0);
50	
51		// Refs
52		let scrollContainer: HTMLDivElement | undefined = $state(undefined);
53	
54		// Constants
55		const MIN_ZOOM = 100;
56		const MAX_ZOOM = 400;
57		const ZOOM_STEP = 50;
58		const PAN_STEP = 50;
59		const DOUBLE_TAP_DELAY = 300; // ms
60	
61		// Pending scroll adjustment for zoom-to-cursor
62		let rafId = 0;
63	
64		// Computed scaled dimensions
65		let scaledWidth = $derived((baseWidth * zoom) / 100);
66		let scaledHeight = $derived((baseHeight * zoom) / 100);
67	
68		/**
69		 * Capture base dimensions on image load — the size the image
70		 * occupies at 100% zoom, fit within the viewport constraints.
71		 */
72		function handleImageLoad(e: Event) {
73			const img = e.target as HTMLImageElement;
74			const natW = img.naturalWidth;
75			const natH = img.naturalHeight;
76			const maxW = window.innerWidth * 0.9;
77			const maxH = window.innerHeight * 0.8;
78			const scale = Math.min(maxW / natW, maxH / natH, 1);
79			baseWidth = natW * scale;
80			baseHeight = natH * scale;
81		}
82	
83		/**
84		 * #{#zom1a} Zoom to a specific level, optionally anchored at a cursor position.
85		 * The point under the cursor stays fixed on screen after zoom.
86		 */
87		function zoomTo(newZoom: number, cursorX?: number, cursorY?: number) {
88			const container = scrollContainer;
89			newZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, newZoom));
90	
91			if (!container || baseWidth === 0) {
92				zoom = newZoom;
93				return;
94			}
95	
96			const oldZoom = zoom;
97			if (newZoom === oldZoom) return;
98	
99			const rect = container.getBoundingClientRect();
100			// Default to center of viewport if no cursor position given
101			const cx = cursorX !== undefined ? cursorX - rect.left : rect.width / 2;
102			const cy = cursorY !== undefined ? cursorY - rect.top : rect.height / 2;
103	
104			// Point in base-image coordinates under the cursor
105			const imageX = (container.scrollLeft + cx) / (oldZoom / 100);
106			const imageY = (container.scrollTop + cy) / (oldZoom / 100);
107	
108			zoom = newZoom;
109	
110			// After Svelte updates the DOM (image resizes), adjust scroll so the
111			// same image point remains under the cursor.
112			const targetScrollLeft = imageX * (newZoom / 100) - cx;
113			const targetScrollTop = imageY * (newZoom / 100) - cy;
114			cancelAnimationFrame(rafId);
115			rafId = requestAnimationFrame(() => {
116				if (container) {
117					container.scrollLeft = targetScrollLeft;
118					container.scrollTop = targetScrollTop;
119				}
120			});
121		}
122	
123		/**
124		 * #{#zom1a} Zoom in by one step (snaps to 50% increments)
125		 */
126		function zoomIn(cursorX?: number, cursorY?: number) {
127			zoomTo(Math.ceil((zoom + 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
128		}
129	
130		/**
131		 * #{#zom1a} Zoom out by one step (snaps to 50% increments)
132		 */
133		function zoomOut(cursorX?: number, cursorY?: number) {
134			zoomTo(Math.floor((zoom - 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
135		}
136	
137		/**
138		 * #{#zom1a} Reset zoom to 100% and scroll to origin
139		 */
140		function resetZoom() {
141			zoom = MIN_ZOOM;
142			if (scrollContainer) {
143				scrollContainer.scrollLeft = 0;
144				scrollContainer.scrollTop = 0;
145			}
146		}
147	
148		/**
149		 * #{#zom1b} #{#pdf1c} Handle mouse wheel zoom — disabled for PDFs.
150		 * Zooms toward the cursor position.
151		 */
152		function handleWheel(e: WheelEvent) {
153			if (isPdf) return; // #{#pdf1c} Let browser PDF viewer handle scroll
154			e.preventDefault();
155			if (e.deltaY < 0) {
156				zoomIn(e.clientX, e.clientY);
157			} else {
158				zoomOut(e.clientX, e.clientY);
159			}
160		}
161	
162		/**
163		 * #{#zom2a} #{#pdf1c} Handle mouse down to start drag-scrolling — disabled for PDFs
164		 */
165		function handleMouseDown(e: MouseEvent) {
166			if (isPdf) return; // #{#pdf1c}
167			if (zoom > MIN_ZOOM) {
168				isDragging = true;
169				dragStartX = e.clientX;
170				dragStartY = e.clientY;
171				scrollStartX = scrollContainer?.scrollLeft ?? 0;
172				scrollStartY = scrollContainer?.scrollTop ?? 0;
173				e.preventDefault();
174			}
175		}
176	
177		/**
178		 * #{#zom2a} Handle mouse move for drag-scrolling
179		 */
180		function handleMouseMove(e: MouseEvent) {
181			if (isDragging && scrollContainer) {
182				scrollContainer.scrollLeft = scrollStartX - (e.clientX - dragStartX);
183				scrollContainer.scrollTop = scrollStartY - (e.clientY - dragStartY);
184			}
185		}
186	
187		/**
188		 * #{#zom2a} Handle mouse up to stop drag-scrolling
189		 */
190		function handleMouseUp() {
191			isDragging = false;
192		}
193	
194		/**
195		 * #{#zom2b} #{#zom5a} #{#pdf1c} Handle keyboard navigation — zoom/pan disabled for PDFs
196		 */
197		function handleKeydown(e: KeyboardEvent) {
198			// Only handle keyboard shortcuts when the image viewer is open
199			if (!show) return;
200	
201			// Escape key closes modal - #{#zom5a} — works for both images and PDFs
202			if (e.key === 'Escape') {
203				close();
204				return;
205			}
206	
207			// #{#pdf1c} Skip zoom/pan keyboard shortcuts for PDFs
208			if (isPdf) return;
209	
210			// Arrow keys for scrolling when zoomed - #{#zom2b}
211			if (zoom > MIN_ZOOM && scrollContainer) {
212				switch (e.key) {
213					case 'ArrowUp':
214						scrollContainer.scrollTop -= PAN_STEP;
215						e.preventDefault();
216						break;
217					case 'ArrowDown':
218						scrollContainer.scrollTop += PAN_STEP;
219						e.preventDefault();
220						break;
221					case 'ArrowLeft':
222						scrollContainer.scrollLeft -= PAN_STEP;
223						e.preventDefault();
224						break;
225					case 'ArrowRight':
226						scrollContainer.scrollLeft += PAN_STEP;
227						e.preventDefault();
228						break;
229				}
230			}
231	
232			// Optional keyboard shortcuts for zoom - #{#zom2b}
233			if (e.key === '+' || e.key === '=') {
234				zoomIn();
235				e.preventDefault();
236			} else if (e.key === '-') {
237				zoomOut();
238				e.preventDefault();
239			} else if (e.key === '0') {
240				resetZoom();
241				e.preventDefault();
242			}
243		}
244	
245		/**
246		 * #{#zom3a} Calculate distance between two touch points
247		 */
248		function getTouchDistance(e: TouchEvent): number {
249			if (e.touches.length < 2) return 0;
250			const touch1 = e.touches[0];
251			const touch2 = e.touches[1];
252			const dx = touch1.clientX - touch2.clientX;
253			const dy = touch1.clientY - touch2.clientY;
254			return Math.sqrt(dx * dx + dy * dy);
255		}
256	
257		/**
258		 * #{#zom3a} Get midpoint between two touch points
259		 */
260		function getTouchMidpoint(e: TouchEvent): { x: number; y: number } {
261			return {
262				x: (e.touches[0].clientX + e.touches[1].clientX) / 2,
263				y: (e.touches[0].clientY + e.touches[1].clientY) / 2
264			};
265		}
266	
267		/**
268		 * #{#zom3a} #{#pdf1c} Handle touch start for pinch zoom and pan — disabled for PDFs
269		 */
270		function handleTouchStart(e: TouchEvent) {
271			if (isPdf) return; // #{#pdf1c}
272			if (e.touches.length === 2) {
273				// Pinch zoom start
274				touchStartDistance = getTouchDistance(e);
275				touchStartZoom = zoom;
276				e.preventDefault();
277			} else if (e.touches.length === 1) {
278				// Check for double tap - #{#zom3a}
279				const now = Date.now();
280				if (now - lastTapTime < DOUBLE_TAP_DELAY) {
281					// Double tap detected — zoom toward tap point
282					if (zoom === MIN_ZOOM) {
283						zoomTo(200, e.touches[0].clientX, e.touches[0].clientY);
284					} else {
285						resetZoom();
286					}
287					e.preventDefault();
288				}
289				lastTapTime = now;
290	
291				// Single touch drag-scroll (if zoomed)
292				if (zoom > MIN_ZOOM) {
293					isDragging = true;
294					dragStartX = e.touches[0].clientX;
295					dragStartY = e.touches[0].clientY;
296					scrollStartX = scrollContainer?.scrollLeft ?? 0;
297					scrollStartY = scrollContainer?.scrollTop ?? 0;
298				}
299			}
300		}
301	
302		/**
303		 * #{#zom3a} #{#pdf1c} Handle touch move for pinch zoom and pan — disabled for PDFs
304		 */
305		function handleTouchMove(e: TouchEvent) {
306			if (isPdf) return; // #{#pdf1c}
307			if (e.touches.length === 2) {
308				// Pinch zoom — anchored at midpoint between fingers
309				const currentDistance = getTouchDistance(e);
310				const mid = getTouchMidpoint(e);
311				const newZoom = touchStartZoom * (currentDistance / touchStartDistance);
312				zoomTo(newZoom, mid.x, mid.y);
313				e.preventDefault();
314			} else if (e.touches.length === 1 && isDragging && scrollContainer) {
315				// Drag to scroll
316				scrollContainer.scrollLeft = scrollStartX - (e.touches[0].clientX - dragStartX);
317				scrollContainer.scrollTop = scrollStartY - (e.touches[0].clientY - dragStartY);
318				e.preventDefault();
319			}
320		}
321	
322		/**
323		 * #{#zom3a} Handle touch end
324		 */
325		function handleTouchEnd() {
326			isDragging = false;
327			touchStartDistance = 0;
328		}
329	
330		/**
331		 * #{#zom2a} #{#zom3a} Wire the pointer/wheel/touch gestures imperatively.
332		 *
333		 * These are mouse/touch *enhancements* on a natively-scrollable container, with
334		 * full keyboard parity provided elsewhere (global arrow/zoom/Escape shortcuts on
335		 * <svelte:window> and the Tab-reachable zoom buttons). There is no ARIA role that
336		 * accurately models a custom zoom/pan surface, so attaching the listeners via an
337		 * action (rather than markup `on*` handlers) keeps the element honestly
338		 * role-less. wheel/touchstart/touchmove are registered non-passive because the
339		 * handlers call preventDefault().
340		 */
341		function gestureSurface(node: HTMLElement) {
342			const active = { passive: false } as AddEventListenerOptions;
343			node.addEventListener('wheel', handleWheel, active);
344			node.addEventListener('mousedown', handleMouseDown);
345			node.addEventListener('touchstart', handleTouchStart, active);
346			node.addEventListener('touchmove', handleTouchMove, active);
347			node.addEventListener('touchend', handleTouchEnd);
348			return {
349				destroy() {
350					node.removeEventListener('wheel', handleWheel);
351					node.removeEventListener('mousedown', handleMouseDown);
