313		function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
314			// #{#dup5a} Pre-compute duplicate IDs when filter is active
315			let dupeIds: Set<string> | null = null;
316			if (filterDuplicates) {
317				const dupes = detectDuplicates(rcts);
318				// eslint-disable-next-line svelte/prefer-svelte-reactivity -- local, non-reactive lookup set built and read within this call; SvelteSet would be inappropriate here
319				dupeIds = new Set<string>();
320				for (const ids of dupes.values()) {
321					for (const id of ids) dupeIds.add(id);
322				}
323			}
324	
325			return rcts.filter((r) => {
326				// #{#dtv3a} Filter by suspicious_date (Needs Review)
327				if (filterNeedsReview && !r.suspicious_date) return false;
328	
329				// #{#dup5a} Filter by duplicate status
330				if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;
331	
332				// #{#sdf1b} Filter by date range using URL parameters
333				if (!matchesDateRange(r.transaction_date, urlDateFrom, urlDateTo)) return false;
334	
335				// Filter by merchant name (local state)
336				if (filterMerchant) {
337					const merchantSearch = filterMerchant.toLowerCase();
338					const merchant = (r.merchant_name || '').toLowerCase();
339					if (!merchant.includes(merchantSearch)) return false;
340				}
341	
342				// Filter by amount range (local state)
343				if (filterAmountMin && r.total_amount !== null) {
344					const minAmount = parseFloat(filterAmountMin);
345					if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
346				}
347				if (filterAmountMax && r.total_amount !== null) {
348					const maxAmount = parseFloat(filterAmountMax);
349					if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
350				}
351	
352				return true;
353			});
354		}
