474		// #{#spl2b} Validate split amount in real-time
475		function getSplitValidationError(amountStr: string, receiptTotal: number | null): string | null {
476			if (!amountStr) return null; // Empty is not an error (just disables button)
477			const amount = parseFloat(amountStr);
478			if (isNaN(amount) || !isFinite(amount)) return 'Please enter a valid amount';
479			if (amount <= 0) return 'Split amount must be greater than zero';
480			if (receiptTotal == null || receiptTotal <= 0) return 'Receipt has no amount to split';
481			if (amount >= receiptTotal) return 'Split amount must be less than the receipt total';
482			if (Math.round(amount * 100) !== amount * 100)
483				return 'Amount can have at most 2 decimal places';
484			return null;
485		}
486	
487		// #{#spl2b} Derived validation for split modal
488		let splitValidationError = $derived(
489			getSplitValidationError(splitAmount, splittingReceipt?.total_amount ?? null)
490		);
491	
492		let splitAmountParsed = $derived(parseFloat(splitAmount));
493		let splitRemainingAmount = $derived(
494			splittingReceipt?.total_amount != null && !isNaN(splitAmountParsed)
495				? Math.round((splittingReceipt.total_amount - splitAmountParsed) * 100) / 100
496				: null
497		);
498	
499		let isSplitValid = $derived(
500			splitAmount !== '' && splitValidationError === null && (splitRemainingAmount ?? 0) > 0
501		);
502	
503		// #{#spl2a} Execute the split
504		async function executeSplit() {
505			if (!splittingReceipt || !isSplitValid) return;
506	
507			isSplitting = true;
508			splitError = null;
509	
510			try {
511				// #{#spl7b} Pass splitDate if different from original
512				const dateOverride =
513					splitDate && splitDate !== splittingReceipt.transaction_date ? splitDate : undefined;
514				await receiptService.splitReceipt(splittingReceipt.id, splitAmountParsed, dateOverride);
515				successMessage = `Receipt split: $${splitAmountParsed.toFixed(2)} + $${splitRemainingAmount?.toFixed(2)}`;
516				setTimeout(() => {
517					successMessage = null;
518				}, 3000);
519				closeSplitModal();
520				await loadReconciliation();
521			} catch (e) {
522				splitError = e instanceof Error ? e.message : 'Failed to split receipt';
523			} finally {
524				isSplitting = false;
525			}
526		}
