528		// #{#spl3a} #{#spl3b} Compute split group info for display
529		function getSplitGroupInfo(
530			receipt: ReceiptRow,
531			allRows: ReconciliationDisplayRow[]
532		): { index: number; total: number; groupAmounts: number[] } | null {
533			const groupId = receipt.split_group_id;
534			if (!groupId) return null;
535	
536			// Find all receipts in this split group from all display rows
537			const groupReceipts: ReceiptRow[] = [];
538			for (const row of allRows) {
539				if (row.receipt?.split_group_id === groupId) {
540					groupReceipts.push(row.receipt);
541				}
542			}
543	
544			if (groupReceipts.length <= 1) return null;
545	
546			// Sort by created_at for consistent ordering
547			groupReceipts.sort((a, b) => a.created_at.localeCompare(b.created_at));
548			const index = groupReceipts.findIndex((r) => r.id === receipt.id);
549	
550			return {
551				index: index + 1,
552				total: groupReceipts.length,
553				groupAmounts: groupReceipts.map((r) => r.total_amount ?? 0)
554			};
555		}
