13		import { onMount } from 'svelte';
14		import { resolve } from '$app/paths';
15		import { goto } from '$app/navigation';
16		import { supabase } from '$lib/supabaseClient';
17		import { ExpenseService } from '$lib/services/ExpenseService';
18		import { CategoryService } from '$lib/services/CategoryService';
19		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
20		import { formatCurrency } from '$lib/utils/formatCurrency';
21		import {
22			buildSpendingReport,
23			type SpendingReport,
24			type SpendingCategory,
25			type Cell,
26			type ReportRow
27		} from '$lib/utils/spendingReport';
28		import {
29			withPriorPeriod,
30			hasPriorData,
31			spendingChange,
32			type SpendingChange
33		} from '$lib/utils/spendingComparison';
34		import {
35			buildSpendingDrilldownParams,
36			type DrilldownScope,
37			type DrilldownColumn
38		} from '$lib/utils/spendingDrilldown';
39		import type { CategoryGroup } from '$lib/types/Hierarchy';
40		import SpendingChart from '$lib/components/SpendingChart.svelte';
41		import type { Session } from '@supabase/supabase-js';
42		import type { PageData } from './$types';
43	
44		let { data }: { data: PageData } = $props();
45	
46		let session: Session | null = $state(null);
47		let familyId: string | null = $state(null);
48		// The selected year comes from the `+page.ts` load (URL `?year=`). Load
49		// re-runs with the right URL on every navigation — arrows, Back, refresh — so
50		// this stays correct where the earlier client-side derivations went stale.
51		let year = $derived(data.year);
52		let view = $state<'table' | 'chart'>('table');
53		let loading = $state(true);
54		let error: string | null = $state(null);
55		let report = $state<SpendingReport | null>(null);
56		// Year-over-year comparison. `compare` is the user's toggle; `hasPrior` says the
57		// prior year actually has data. The effective `comparing` gates both views, so
58		// the toggle can stay pressed while inert on a year whose predecessor is empty.
59		let compare = $state(false);
60		let hasPrior = $state(false);
61		const priorYear = $derived(year - 1);
62		const comparing = $derived(compare && hasPrior);
63		// Kept in state (not just local to loadReport) so cell drill-down can expand a
64		// Grouping/Importance to its member category ids.
65		let categories = $state<SpendingCategory[]>([]);
66		let groups = $state<CategoryGroup[]>([]);
67	
68		onMount(async () => {
69			const { data } = await supabase.auth.getSession();
70			session = data.session;
71			if (!session) {
72				loading = false;
73				return;
74			}
75	
76			familyId = await getDefaultFamilyId();
77			if (!familyId) {
78				error = 'No family found. Please contact support.';
79				loading = false;
80			}
81		});
