83		// Load (or reload) whenever the resolved family or the URL year changes. The
84		// URL is the source of truth for `year`, so a refresh / back-navigation to a
85		// past year reloads that year rather than the current one.
86		$effect(() => {
87			const reportYear = year; // track the derived year
88			if (session?.user && familyId) {
89				loadReport(reportYear);
90			}
91		});
92	
93		async function loadReport(reportYear: number) {
94			if (!session?.user || !familyId) return;
95	
96			try {
97				loading = true;
98				error = null;
99	
100				const categoryService = new CategoryService(supabase);
101				const expenseService = new ExpenseService(supabase);
102	
103				// Seed the default hierarchy the first time a family opens the report
104				// (idempotent server-side), mirroring how categories self-initialize.
105				let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
106				if (importanceAreas.length === 0) {
107					await categoryService.createDefaultHierarchy(familyId);
108					importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
109				}
110	
111				// The prior year is fetched alongside so the comparison toggle repaints
112				// instantly (no refetch) and we know up-front whether to enable it. A
113				// family's yearly receipt count is small, so the extra query is negligible.
114				const [loadedGroups, loadedCategories, expenses, priorExpenses] = await Promise.all([
115					categoryService.getFamilyGroups(familyId),
116					categoryService.getFamilyCategories(familyId),
117					expenseService.getExpenses(session.user.id, {
118						startDate: `${reportYear}-01-01`,
119						endDate: `${reportYear}-12-31`
120					}),
121					expenseService.getExpenses(session.user.id, {
122						startDate: `${reportYear - 1}-01-01`,
123						endDate: `${reportYear - 1}-12-31`
124					})
125				]);
126	
127				groups = loadedGroups;
128				categories = loadedCategories;
129				const current = buildSpendingReport(
130					expenses,
131					loadedCategories,
132					loadedGroups,
133					importanceAreas,
134					reportYear
135				);
136				const prior = buildSpendingReport(
137					priorExpenses,
138					loadedCategories,
139					loadedGroups,
140					importanceAreas,
141					reportYear - 1
142				);
143				hasPrior = hasPriorData(prior);
144				// Attaches same-period prior-year totals to `current`'s rows (Jan → the
145				// year's last visible month). Harmless when there's no prior data.
146				report = withPriorPeriod(current, prior);
147			} catch (err) {
148				console.error('Error loading spending report:', err);
149				error = err instanceof Error ? err.message : 'Failed to load the spending report';
150			} finally {
151				loading = false;
152			}
153		}
154	
155		function changeYear(delta: number) {
