1	<script lang="ts">
2		/**
3		 * Spending hierarchy editor
4		 *
5		 * Lets the family maintainer restructure the spending hierarchy without SQL:
6		 *   - assign a Category to a Grouping (or back to Uncategorized)
7		 *   - move a Grouping to a different Area of Importance
8		 *   - add a new Grouping under an Area of Importance
9		 *   - rename a Grouping
10		 *
11		 * The report attaches Importance to the Grouping, so moving a Grouping
12		 * re-buckets all its Categories at once. Categories with no Grouping land in
13		 * the "Unassigned" bucket up top — the whole reason this editor exists (the
14		 * seed maps categories by name, so custom/renamed ones start unassigned).
15		 *
16		 * Tree shaping is the pure `buildHierarchyTree`; this page loads the three
17		 * hierarchy tables, renders the tree, and calls CategoryService mutations,
18		 * reloading after each. Design: docs/plans/2026-07-09-spending-report-design.md
19		 */
20	
21		import { onMount } from 'svelte';
22		import { resolve } from '$app/paths';
23		import { supabase } from '$lib/supabaseClient';
24		import { CategoryService } from '$lib/services/CategoryService';
25		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
26		import { buildHierarchyTree, type HierarchyTree } from '$lib/utils/hierarchyTree';
27		import HierarchyEditor from '$lib/components/HierarchyEditor.svelte';
28		import type { ImportanceArea } from '$lib/types/Hierarchy';
29		import type { Session } from '@supabase/supabase-js';
30	
31		let session: Session | null = $state(null);
32		let familyId: string | null = $state(null);
33		let loading = $state(true);
34		let saving = $state(false);
35		let error: string | null = $state(null);
36		let tree = $state<HierarchyTree | null>(null);
37		let importanceAreas = $state<ImportanceArea[]>([]);
38		// Expense count per unassigned category id, shown after the name in the editor.
39		let expenseCounts = $state<Record<string, number>>({});
40	
41		const service = new CategoryService(supabase);
42	
43		onMount(async () => {
44			const { data } = await supabase.auth.getSession();
45			session = data.session;
46			if (!session) {
47				loading = false;
48				return;
49			}
50	
51			familyId = await getDefaultFamilyId();
52			if (!familyId) {
53				error = 'No family found. Please contact support.';
54				loading = false;
55				return;
56			}
57	
58			await load();
59		});
60	
61		async function load() {
62			if (!familyId) return;
63	
64			try {
65				loading = true;
66				error = null;
67	
68				// Self-seed the default hierarchy if this family has none yet (mirrors
69				// the /spending report's lazy-init), so the editor is never empty.
70				let areas = await service.getFamilyImportanceAreas(familyId);
71				if (areas.length === 0) {
72					await service.createDefaultHierarchy(familyId);
73					areas = await service.getFamilyImportanceAreas(familyId);
74				}
75	
76				const [groups, categories] = await Promise.all([
77					service.getFamilyGroups(familyId),
78					service.getFamilyCategories(familyId)
79				]);
80	
81				importanceAreas = areas;
82				tree = buildHierarchyTree(areas, groups, categories);
83	
84				// Only the unassigned categories show a count, so fetch just those (an
85				// exact head-count each, in parallel). A failed count is left off rather
86				// than failing the whole page load.
87				const counts: Record<string, number> = {};
88				await Promise.all(
89					tree.unassigned.map(async (category) => {
90						try {
91							counts[category.id] = await service.countCategoryExpenses(category.id);
92						} catch {
93							// Skip this category's count; the name still renders without one.
94						}
95					})
96				);
97				expenseCounts = counts;
98			} catch (err) {
99				console.error('Error loading hierarchy:', err);
100				error = err instanceof Error ? err.message : 'Failed to load the hierarchy';
101			} finally {
102				loading = false;
103			}
104		}
105	
106		/** Run a mutation, surface any error in the UI, then reload the tree. */
107		async function mutate(action: () => Promise<void>) {
108			try {
109				saving = true;
110				error = null;
111				await action();
112				await load();
113			} catch (err) {
114				console.error('Error saving hierarchy change:', err);
115				error = err instanceof Error ? err.message : 'Failed to save the change';
116			} finally {
117				saving = false;
118			}
119		}
120	
121		function assignCategory(categoryId: string, groupId: string | null) {
122			mutate(() => service.assignCategoryToGroup(categoryId, groupId));
123		}
124	
125		function moveGroup(groupId: string, importanceAreaId: string) {
126			if (!importanceAreaId) return;
127			mutate(() => service.moveGroupToImportance(groupId, importanceAreaId));
128		}
129	
130		function createGroup(name: string, importanceAreaId: string) {
131			const fid = familyId;
132			if (!fid || !name.trim() || !importanceAreaId) return;
133			mutate(async () => {
134				await service.createGroup(fid, name, importanceAreaId);
135			});
136		}
137	
138		function renameGroup(groupId: string, name: string) {
139			if (!name.trim()) return;
140			mutate(() => service.renameGroup(groupId, name));
141		}
142	
143		// Delete a category entirely. The DB nulls the category on its expenses
144		// (expense_categories.category_id ON DELETE SET NULL) and cascade-removes any
145		// vendor rules, so no expense history is lost — but it's irreversible, so we
146		// confirm first and surface how many expenses will drop to Uncategorized.
147		async function deleteCategory(categoryId: string, name: string) {
148			let count: number | null = null;
149			try {
150				count = await service.countCategoryExpenses(categoryId);
151			} catch {
152				// If the count can't be fetched, fall back to a generic warning rather
153				// than blocking the delete.
154				count = null;
155			}
156	
157			const impact =
158				count === null
159					? 'Any expenses using it will become Uncategorized'
160					: count === 0
161						? 'It has no expenses'
162						: `Its ${count} expense${count === 1 ? '' : 's'} will become Uncategorized`;
163	
164			if (
165				!confirm(
166					`Delete the category “${name}”? ${impact}, and any vendor auto-categorization rules for it will be removed. This can’t be undone.`
167				)
168			) {
169				return;
170			}
171	
172			await mutate(() => service.deleteCategory(categoryId));
173		}
174	
175		const hasHierarchy = $derived(tree !== null && tree.importances.length > 0);
176	</script>
177	
178	<svelte:head>
179		<title>Edit spending hierarchy — YFL Expense Tracker</title>
180	</svelte:head>
181	
182	<div class="hierarchy-editor max-w-5xl">
183		<div class="mb-6 flex flex-wrap items-center justify-between gap-3">
184			<div>
185				<h1 class="mb-2 text-2xl font-bold">Edit spending hierarchy</h1>
186				<p class="text-gray-600">
187					Assign each Category to a Grouping, and each Grouping to an Area of Importance. Add or
188					rename Groupings as needed. Changes save immediately and reshape the Spending report.
189				</p>
190			</div>
191			<a
192				href={resolve('/spending')}
193				class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
194			>
195				← Back to Spending
196			</a>
197		</div>
198	
199		{#if error}
200			<div class="mb-4 rounded border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>
201		{/if}
202	
203		{#if loading}
204			<div class="flex items-center justify-center p-8 text-gray-500">Loading hierarchy…</div>
205		{:else if !session}
206			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
207				Please log in to edit the hierarchy.
208			</div>
209		{:else if !hasHierarchy}
210			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
211				No hierarchy found for this family.
212			</div>
213		{:else if tree}
214			<HierarchyEditor
215				{tree}
216				{importanceAreas}
217				{saving}
218				onAssignCategory={assignCategory}
219				onMoveGroup={moveGroup}
220				onCreateGroup={createGroup}
221				onRenameGroup={renameGroup}
222				onDeleteCategory={deleteCategory}
223				{expenseCounts}
224			/>
225		{/if}
