1	<script lang="ts">
2		/**
3		 * SpendingChart — an accordion magnitude bar chart of the Spending Report.
4		 *
5		 * One solid bar per Grouping = its year-to-date total, coloured by Area of
6		 * Importance. Each Grouping can be **expanded in place** (via its ± bracket) to
7		 * reveal its Category bars while siblings stay visible; any number can be open
8		 * at once. Two bracket rows under the axis carry the hierarchy: a per-Grouping
9		 * toggle row, then the Area-of-Importance row. Every bar carries a value label
10		 * so small bars stay readable next to a dominant one.
11		 *
12		 * When `compare` is on, each Grouping shows a faded prior-year bar beside the
13		 * current-year bar (side by side).
14		 *
15		 * (Month-by-month detail lives in the Table view and the future trend chart.)
16		 *
17		 * Built on LayerChart's <BarChart> for scales + axes; the bars themselves are
18		 * drawn as overlays (so current/prior sit side by side) and LayerChart's own
19		 * bars are hidden. Data shaping is the pure `buildSpendingChart`.
20		 * Design: docs/plans/2026-07-09-spending-report-design.md
21		 */
22		import { BarChart, Text } from 'layerchart';
23		import type { ChartState } from 'layerchart';
24		import { SvelteSet } from 'svelte/reactivity';
25		import { buildSpendingChart, type ChartBar } from '$lib/utils/spendingChart';
26		import type { SpendingReport } from '$lib/utils/spendingReport';
27		import { spendingChange } from '$lib/utils/spendingComparison';
28		import { formatCurrency } from '$lib/utils/formatCurrency';
29	
30		// `compare` shows a faded prior-year bar beside each current-year bar (and adds
31		// the prior total + change to the tooltip). The prior totals ride along on the
32		// report's rows via `withPriorPeriod`; the parent only flips the flag.
33		let { report, compare = false }: { report: SpendingReport; compare?: boolean } = $props();
34	
35		const priorYear = $derived(report.year - 1);
36	
37		// Grouping names currently expanded to their Categories (accordion; many at once).
38		const expandedGroups = new SvelteSet<string>();
39	
40		const model = $derived(buildSpendingChart(report, expandedGroups));
41	
42		function toggleGroup(name: string) {
43			if (expandedGroups.has(name)) expandedGroups.delete(name);
44			else expandedGroups.add(name);
45		}
46	
47		// LayerChart data: a stable unique id per bar (names can repeat across groups,
48		// which would collide on the band scale), plus the fields the chart reads.
49		// LayerChart draws no visible bars (its own bars are hidden — see props.bars);
50		// we render them as overlays. `total` here only sizes the y-domain, so when
51		// comparing it's the taller of the two years, ensuring a tall prior bar fits.
52		const data = $derived(
53			model.bars.map((bar, i) => ({
54				id: `b${i}`,
55				name: bar.name,
56				kind: bar.kind,
57				importance: bar.importance,
58				total: compare ? Math.max(bar.total, bar.priorTotal ?? 0) : bar.total
59			}))
60		);
61	
62		// Validated categorical palette (dataviz), assigned to Importances in report
63		// order; the no-importance (Uncategorized) bars get a neutral gray.
64		const IMPORTANCE_PALETTE = ['#4f46e5', '#0d9488', '#d97706', '#7c3aed', '#db2777'];
65		const NEUTRAL = '#9ca3af';
66	
67		const importanceColors = $derived.by(() => {
68			const domain: string[] = [];
69			const range: string[] = [];
70			let next = 0;
71			for (const bar of model.bars) {
72				if (domain.includes(bar.importance)) continue;
73				domain.push(bar.importance);
74				if (bar.importance === '') {
75					range.push(NEUTRAL);
76				} else {
77					range.push(IMPORTANCE_PALETTE[next % IMPORTANCE_PALETTE.length]);
78					next++;
79				}
80			}
81			return { domain, range };
82		});
83	
84		const cDomain = $derived(importanceColors.domain);
85		const cRange = $derived(importanceColors.range);
86	
87		function importanceColor(name: string): string {
88			const idx = importanceColors.domain.indexOf(name);
89			return idx >= 0 ? importanceColors.range[idx] : NEUTRAL;
90		}
91	
92		// Bound LayerChart state; its scales position the brackets, labels, and toggles.
93		let chartContext = $state<ChartState | undefined>(undefined);
94	
95		/** The x-scale is a band scale for categorical bars; AnyScale hides bandwidth. */
96		interface BandScale {
97			(value: string): number | undefined;
98			bandwidth(): number;
99		}
100		type LinearScale = (value: number) => number;
101	
102		function bandScale(): BandScale | null {
103			const xScale = chartContext?.xScale as unknown as BandScale | undefined;
104			return xScale && typeof xScale.bandwidth === 'function' ? xScale : null;
105		}
106	
107		// Truncate a tick label to what fits one bar width (~6.5px per char at the tick
108		// font size); the full name is always available in the hover tooltip.
109		function fitLabel(name: string): string {
110			const bandwidth = bandScale()?.bandwidth() ?? 0;
111			const maxChars = Math.max(3, Math.floor(bandwidth / 6.5));
112			return name.length > maxChars ? `${name.slice(0, maxChars - 1).trimEnd()}…` : name;
113		}
114	
115		interface Span {
116			key: string;
117			left: number;
118			width: number;
119		}
120	
121		/** Pixel span of bars [start..end] (inclusive) from the band scale, or null. */
122		function spanOf(start: number, end: number): Omit<Span, 'key'> | null {
123			const ctx = chartContext;
124			const xScale = bandScale();
125			if (!ctx || !xScale) return null;
126			const a = xScale(`b${start}`);
127			const b = xScale(`b${end}`);
128			if (typeof a !== 'number' || typeof b !== 'number') return null;
129			return { left: ctx.padding.left + a, width: b + xScale.bandwidth() - a };
130		}
131	
132		interface GroupBracket extends Span {
133			groupName: string;
134			importance: string;
135			expanded: boolean;
136		}
137	
