139		// expanded (its category bars).
140		const groupBrackets = $derived.by((): GroupBracket[] => {
141			if (!bandScale()) return [];
142			const out: GroupBracket[] = [];
143			let i = 0;
144			while (i < model.bars.length) {
145				const g = model.bars[i].groupName;
146				let j = i;
